int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int i, matrix_index;
    int matrix_present[4];

    matrix_present[0] = get_bits1(gb); /* intra_matrix_present */
    matrix_present[1] = get_bits1(gb); /* non_intra_matrix_present */
    matrix_present[2] = get_bits1(gb); /* chroma_intra_matrix_present */
    matrix_present[3] = get_bits1(gb); /* chroma_non_intra_matrix_present */

    for (i = 0; i < 4; i++) {
        if (matrix_present[i]) {
            if (get_bits_left(gb) < 64 * 8) {
                return AVERROR_INVALIDDATA;
            }

            for (matrix_index = 0; matrix_index < 64; matrix_index++) {
                switch (i) {
                    case 0:
                        s->intra_matrix[scan_table[matrix_index]] = get_bits(gb, 8);
                        break;
