            }
        }
    }

    skip_bits(gb, 8 - (get_bits_count(gb) & 7)); /* align to byte boundary */
    skip_bits1(gb); /* skip start code */

    return 0;
}

int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int i, matrix_present;
    int16_t *q_matrix;

    // Intra quantization matrix
    matrix_present = get_bits1(gb);
    if (matrix_present) {
        if (get_bits_left(gb) < 64) {
            return AVERROR_INVALIDDATA;
        }
        q_matrix = s->intra_matrix;
        for (i = 0; i < 64; i++) {
            q_matrix[i] = get_bits(gb, 8);
        }
    }

    // Non-intra quantization matrix
    matrix_present = get_bits1(gb);
    if (matrix_present) {
        if (get_bits_left(gb) < 64) {
            return AVERROR_INVALIDDATA;
        }
        q_matrix = s->inter_matrix;
        for (i = 0; i < 64; i++) {
            q_matrix[i] = get_bits(gb, 8);
        }
    }

    // Chroma intra quantization matrix
    matrix_present = get_bits1(gb);
    if (matrix_present) {
        if (get_bits_left(gb) < 64) {
            return AVERROR_INVALIDDATA;
        }
        q_matrix = s->chroma_intra_matrix;
        for (i = 0; i < 64; i++) {
            q_matrix[i] = get_bits(gb, 8);
        }
    }

    // Chroma non-intra quantization matrix
    matrix_present = get_bits1(gb);
    if (matrix_present) {
        if (get_bits_left(gb) < 64) {
            return AVERROR_INVALIDDATA;
        }
        q_matrix = s->chroma_inter_matrix;
        for (i = 0; i < 64; i++) {
            q_matrix[i] = get_bits(gb, 8);
        }
    }

    // Advance to next start code
    skip_bits(gb, 8 - (get_bits_count(gb) & 7));
    skip_bits_long(gb, 32);

    return 0;
}

int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int i, ret;

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++) {
            s->intra_matrix[i] = get_bits(gb, 8);
            if (s->intra_matrix[i] == 0) {
                return AVERROR_INVALIDDATA;
            }
        }
    }

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++) {
            s->inter_matrix[i] = get_bits(gb, 8);
            if (s->inter_matrix[i] == 0) {
                return AVERROR_INVALIDDATA;
            }
        }
    }

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++) {
            s->chroma_intra_matrix[i] = get_bits(gb, 8);
            if (s->chroma_intra_matrix[i] == 0) {
                return AVERROR_INVALIDDATA;
            }
        }
    }

    if (get_bits1(gb)) {
        for (i = 0; i < 64; i++) {
            s->chroma_inter_matrix[i] = get_bits(gb, 8);
            if (s->chroma_inter_matrix[i] == 0) {
                return AVERROR_INVALIDDATA;
            }
        }
    }

    ret = skip_bits(gb, (get_bits_count(gb) & ~7) + 8);
    if (ret < 0) {
        return ret;
    }

    skip_to_next_start_code(gb);
    return 0;
}

int read_quant_matrices(MpegEncContext *s, GetBitContext *gb) {
    int matrix_index, i, ret;

    for (matrix_index = 0; matrix_index < 4; matrix_index++) {
        int present = get_bits1(gb);
        if (!present) {
            continue;
        }

        if (get_bits_left(gb) < 64) {
            return AVERROR_INVALIDDATA;
        }

        for (i = 0; i < 64; i++) {
            int value = get_bits(gb, 8);
            if (value == 0) {
                return AVERROR_INVALIDDATA;
            }

            if (matrix_index == 0) {
                s->intra_matrix[i] = value;
            } else if (matrix_index == 1) {
                s->non_intra_matrix[i] = value;
            } else if (matrix_index == 2) {
                s->chroma_intra_matrix[i] = value;
            } else {
                s->chroma_non_intra_matrix[i] = value;
            }
        }
    }

    skip_bits(gb, get_bits_left(gb) & 7);

    return 0;
}
